import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.B0p3fmqd.js";const n="/script-documentation/images/pawnshop.jpg",m=JSON.parse('{"title":"Pawnshop Management","description":"","frontmatter":{},"headers":[],"relativePath":"pawnshop/index.md","filePath":"pawnshop/index.md","lastUpdated":1791039789000}'),r={name:"pawnshop/index.md"};function i(d,e,l,c,p,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="pawnshop-management" tabindex="-1">Pawnshop Management <a class="header-anchor" href="#pawnshop-management" aria-label="Permalink to &quot;Pawnshop Management&quot;">​</a></h1><p><img src="'+n+'" alt="Pawnshop Management"></p><p>A player owned pawnshop. Players buy goods over the counter, owners set prices, and stock is run out to a buyer for profit.</p><div class="info custom-block"><p class="custom-block-title">Version 2.1.0</p><p>Requires <code>community_bridge</code>, <code>ox_lib</code> and <code>oxmysql</code>. The default categories use standard inventory items only.</p></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Player owned shops.</strong> Buy a pawnshop, hire staff and set grades.</li><li><strong>Pricing.</strong> Owners and managers set what the shop pays for each item.</li><li><strong>Export runs.</strong> Load a van with stock and drive it to a buyer. The driver keeps a cut and the business keeps the rest.</li><li><strong>Categories.</strong> Each file in <code>shared/categories</code> is one category. Tick which categories each shop buys when you place it.</li><li><strong>Anti-farming.</strong> Repeated sales of the same item are paid less, and impossible requests are blocked.</li><li><strong>Admin tools.</strong> Place everything in game with <code>/pawncreator</code>.</li></ul><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li><a href="/script-documentation/pawnshop/installation">Install the script</a></li><li><a href="/script-documentation/pawnshop/configuration">Configure it</a></li></ol>',8)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
